package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public final class EpisodeActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private LinearLayout list;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=TvUi.root(this);root.addView(TvUi.text(this,getIntent().getStringExtra("title"),26,TvUi.INK));Button back=TvUi.button(this,"返回搜索");root.addView(back);back.setOnClickListener(v->finish());status=TvUi.text(this,"正在读取播放列表…",16,TvUi.MUTED);root.addView(status);ScrollView scroll=new ScrollView(this);list=TvUi.col(this);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));load();}
 private void load(){String api=getIntent().getStringExtra("api"),id=getIntent().getStringExtra("movie"),source=getIntent().getStringExtra("source"),site=getIntent().getStringExtra("site");worker.execute(()->{try{VodApi.Movie chosen=VodCache.get(api,id);if(chosen==null){List<VodApi.Movie> movies=VodApi.parse(PublicHttp.get(VodApi.query(api,"ids",id)));for(VodApi.Movie m:movies)if(m.id.equals(id)){chosen=m;VodCache.put(api,m);break;}}if(chosen==null)throw new java.io.IOException("接口没有返回此影片详情");String json=VodApi.episodes(chosen,site,source);List<CatalogItem> episodes=CatalogParser.parse(json);new CatalogRepository(this).merge(json,"films","未分类");runOnUiThread(()->{if(isDestroyed())return;status.setText(episodes.size()+" 项 · 直接播放地址（未进行播放验证）");ArrayList<String> ids=new ArrayList<>();for(CatalogItem entry:episodes)ids.add(entry.id);for(int n=0;n<episodes.size();n++){final int index=n;Button button=TvUi.button(this,episodes.get(n).title);list.addView(button);button.setOnClickListener(v->startActivity(new Intent(this,PlayerActivity.class).putStringArrayListExtra("ids",ids).putExtra("index",index)));}});}catch(Exception e){String message=e.getMessage();runOnUiThread(()->{if(isDestroyed())return;status.setText("读取失败："+message);Button retry=TvUi.button(this,"重试");list.addView(retry);retry.setOnClickListener(v->{list.removeAllViews();status.setText("正在重试…");load();});});}});}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
